            object.add(treeWriter.pendingName, JsonNull.INSTANCE);
          }
          treeWriter.pendingName = null;
        } else if (treeWriter.stack.isEmpty()) {
          treeWriter.product = JsonNull.INSTANCE;
        } else {
          JsonElement top = treeWriter.stack.get(treeWriter.stack.size() - 1);
          if (top instanceof JsonArray) {
            ((JsonArray) top).add(JsonNull.INSTANCE);
          } else {
            throw new IllegalStateException();
          }
        }
        return;
      }

      if (element.isJsonPrimitive()) {
        JsonPrimitive primitive = (JsonPrimitive) element;
        Object encoded = primitive == this ? this.value : primitive.value;
        JsonPrimitive encodedPrimitive;
